export class CommandClient {
  public readonly transport: AshTransport;
  /** The live connection every subscription and live query shares. */
  public readonly subscriptions: AshSubscriptionClient;
  public readonly cab: CabClient;
  public readonly depot: DepotClient;
  public readonly rider: RiderClient;
  public readonly trip: TripClient;
  public readonly serviceZone: ServiceZoneClient;
  public readonly telemetrySample: TelemetrySampleClient;
  public readonly fleetAlert: FleetAlertClient;
  public readonly pulseSample: PulseSampleClient;
  public readonly fleet: FleetDomainClient;
  public readonly riders: RidersDomainClient;
  public readonly rides: RidesDomainClient;
  public readonly telemetry: TelemetryDomainClient;

  constructor(config: AshClientConfig) {
    this.transport = new AshTransport(config);
    this.subscriptions = new AshSubscriptionClient(config);
    this.cab = new CabClient(this.transport, this.subscriptions);
    this.depot = new DepotClient(this.transport, this.subscriptions);
    this.rider = new RiderClient(this.transport, this.subscriptions);
    this.trip = new TripClient(this.transport, this.subscriptions);
    this.serviceZone = new ServiceZoneClient(this.transport, this.subscriptions);
    this.telemetrySample = new TelemetrySampleClient(this.transport, this.subscriptions);
    this.fleetAlert = new FleetAlertClient(this.transport, this.subscriptions);
    this.pulseSample = new PulseSampleClient(this.transport, this.subscriptions);
    this.fleet = new FleetDomainClient(this.transport, this.subscriptions);
    this.riders = new RidersDomainClient(this.transport, this.subscriptions);
    this.rides = new RidesDomainClient(this.transport, this.subscriptions);
    this.telemetry = new TelemetryDomainClient(this.transport, this.subscriptions);
  }
}

export function createCommandClient(config: AshClientConfig): CommandClient {
  return new CommandClient(config);
}

